 await p.getByText('操作步骤',{exact:true}).click();await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:`${dir}/result-${width}-${mode}.png`,fullPage:true});
 await p.getByRole('combobox',{name:'表格单位',exact:true}).selectOption('mL');assert((await p.locator('.reaction-mix-result').innerText()).includes('0.2376 mL'));const converted=await copy(p,'复制');assert(converted.includes('Master mix每反应: 0.005 mL; 预混; 整批: 0.132 mL;'));
