await p.locator('[data-mix-field=volume]').first().fill('5');await p.getByRole('combobox',{name:'计算依据',exact:true}).first().selectOption('concentration');await p.locator('[data-mix-field=stock]').fill('1');await p.locator('[data-mix-field=target]').fill('2000');await p.getByRole('button',{name:'G_one',exact:true}).click();await p.getByRole('button',{name:'计算',exact:true}).click();await p.waitForFunction(()=>document.activeElement?.getAttribute('data-mix-field')==='target');
